import dspy


class MaybeFails(dspy.Module):
    def forward(self, value):
        if value == 2:
            raise ValueError("boom")
        return dspy.Prediction(answer=str(value * 10))


def exact_metric(example, prediction, trace=None):
    return float(prediction.answer == example.answer)


devset = [
    dspy.Example(value=1, answer="10").with_inputs("value"),
    dspy.Example(value=2, answer="20").with_inputs("value"),
    dspy.Example(value=3, answer="30").with_inputs("value"),
]

result = dspy.Evaluate(
    devset=devset,
    metric=exact_metric,
    display_progress=False,
    max_errors=2,
    failure_score=-0.25,
)(MaybeFails())

scores = [score for _, _, score in result.results]
failed_prediction = result.results[1][1]

print("per_example_scores:", scores)
print("failed_prediction:", failed_prediction)
print("aggregate_score:", result.score)

assert scores == [1.0, -0.25, 1.0]
assert failed_prediction.toDict() == {}
assert result.score == 58.33
